// Sales report. Used by the finance export (export.js) and the weekly digest (digest.js).
// The layout is parsed by the finance team's import, so do not move columns around.
// TODO: US region once the tax rules are clear

const REGIONS = {
  DE: { title: 'Germany', taxRate: 0.19, thousands: '.', decimal: ',', symbol: '€', symbolFirst: false },
  FR: { title: 'France', taxRate: 0.2, thousands: ' ', decimal: ',', symbol: '€', symbolFirst: false },
  UK: { title: 'United Kingdom', taxRate: 0.2, thousands: ',', decimal: '.', symbol: '£', symbolFirst: true },
};

const REGION_ORDER = ['DE', 'FR', 'UK'];
const PRODUCT_COLUMN_WIDTH = 20;
const UNITS_COLUMN_WIDTH = 5;
const MONEY_COLUMN_WIDTH = 14;
const BULK_DISCOUNT_MIN_UNITS = 100;
const BULK_DISCOUNT_FACTOR = 0.95;
const LARGE_ORDER_MIN_AMOUNT = 10000;
const MONTH_PATTERN = /^\d{4}-\d{2}$/;

export function formatMoney(amount, region) {
  const style = REGIONS[region];
  if (!style) {
    throw new Error('unknown region: ' + region);
  }
  const sign = amount < 0 ? '-' : '';
  const [integerPart, cents] = Math.abs(amount).toFixed(2).split('.');
  const number = groupThousands(integerPart, style.thousands) + style.decimal + cents;
  return sign + (style.symbolFirst ? style.symbol + number : number + ' ' + style.symbol);
}

export function buildReport(sales, options) {
  options = options || {};
  validateOptions(options);

  const rows = selectRows(sales, options.month);
  const lines = [options.month ? 'SALES REPORT ' + options.month : 'SALES REPORT', ''];
  const totals = { rows: 0, largeOrders: 0 };

  for (const region of REGION_ORDER) {
    const regionSales = rows.filter((sale) => sale.region === region && sale.units > 0);
    if (regionSales.length > 0) {
      lines.push(...regionSection(region, regionSales, totals));
    }
  }

  if (totals.rows === 0) {
    lines.push('No sales.');
  } else {
    lines.push('Rows: ' + totals.rows, 'Large orders: ' + totals.largeOrders);
  }
  return lines.join('\n') + '\n';
}

function validateOptions({ format, month }) {
  if (format && format !== 'text') {
    throw new Error('unsupported format: ' + format);
  }
  if (month && !MONTH_PATTERN.test(month)) {
    throw new Error('bad month: ' + month);
  }
}

function selectRows(sales, month) {
  const rows = month ? sales.filter((sale) => sale.date.slice(0, 7) === month) : sales.slice();
  return rows.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
}

function regionSection(region, regionSales, totals) {
  const lines = ['== ' + REGIONS[region].title + ' =='];
  let subtotal = 0;
  for (const sale of regionSales) {
    const amount = grossAmount(sale, REGIONS[region].taxRate);
    const isLarge = amount >= LARGE_ORDER_MIN_AMOUNT;
    lines.push(saleLine(sale, amount, region) + (isLarge ? ' *' : ''));
    subtotal += amount;
    totals.rows++;
    if (isLarge) totals.largeOrders++;
  }
  lines.push(`Subtotal ${region}: ${formatMoney(subtotal, region)}`, '');
  return lines;
}

function grossAmount(sale, taxRate) {
  let net = sale.units * sale.unitPrice;
  if (sale.discountPct) {
    net -= (net * sale.discountPct) / 100;
  }
  if (sale.units >= BULK_DISCOUNT_MIN_UNITS) {
    net *= BULK_DISCOUNT_FACTOR;
  }
  net = roundToCents(net);
  const tax = roundToCents(net * taxRate);
  return roundToCents(net + tax);
}

function saleLine(sale, amount, region) {
  return [
    truncate(sale.product, PRODUCT_COLUMN_WIDTH).padEnd(PRODUCT_COLUMN_WIDTH),
    String(sale.units).padStart(UNITS_COLUMN_WIDTH),
    formatSaleAmount(amount, region).padStart(MONEY_COLUMN_WIDTH),
  ].join(' ');
}

// The finance import has always received this odd rendering of negative DE/UK line amounts
// (the minus sign counts as a digit when grouping, e.g. "-.178,14 €", "£-1,140.00"). Keep it byte-for-byte.
function formatSaleAmount(amount, region) {
  if (!(amount < 0) || region === 'FR') {
    return formatMoney(amount, region);
  }
  const style = REGIONS[region];
  const [signedInteger, cents] = amount.toFixed(2).split('.');
  const number = signedInteger.replace(/(?<=.)(?=(?:.{3})+$)/g, style.thousands) + style.decimal + cents;
  return style.symbolFirst ? style.symbol + number : number + ' ' + style.symbol;
}

function truncate(text, maxLength) {
  return text.length > maxLength ? text.slice(0, maxLength - 1) + '…' : text;
}

function roundToCents(value) {
  return Math.round(value * 100) / 100;
}

function groupThousands(digits, separator) {
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, separator);
}

